def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    ones = [(y, x) for y in range(H) for x in range(W) if g[y, x] != bg]

    # find the 180-degree rotation centre (cy2/2, cx2/2) that maps the most
    # figure cells onto other figure cells
    best = None
    for cy2 in range(0, 2 * H - 1):
        for cx2 in range(0, 2 * W - 1):
            m = 0
            for y, x in ones:
                yy, xx = cy2 - y, cx2 - x
                if 0 <= yy < H and 0 <= xx < W and g[yy, xx] != bg:
                    m += 1
            if best is None or m > best[0]:
                best = (m, cy2, cx2)
    _, cy2, cx2 = best

    # cells of the rotated image that are still background -> colour 2
    missing = set()
    for y, x in ones:
        yy, xx = cy2 - y, cx2 - x
        if 0 <= yy < H and 0 <= xx < W and g[yy, xx] == bg:
            missing.add((yy, xx))

    out = g.copy()
    for row in sorted({y for y, _ in missing}):
        for y, x in missing:
            if y == row:
                out[y, x] = 2
        emit(out, f"row {row}: paint the 180-degree-rotated image cells that are missing (centre ({cy2/2}, {cx2/2})) in colour 2")

    emit(out, "figure completed to full point symmetry")
    return out
